INSERT INTO posts (title, slug, excerpt, content, status, author_id, category_id, primary_subtopic_id, reading_time, meta_title, meta_description, featured_score, published_at, ai_status, image_alt) VALUES
('مقدمه‌ای بر مکانیک کوانتومی', 'intro-to-quantum-mechanics', 'مکانیک کوانتومی شاخه‌ای از فیزیک است که رفتار ذرات ریز را در مقیاس اتمی و زیراتمی توصیف می‌کند.', '# مقدمه‌ای بر مکانیک کوانتومی\n\nمکانیک کوانتومی یکی از مهم‌ترین دستاوردهای فیزیک در سده بیستم است. برخلاف مکانیک کلاسیک، در این نظریه ذرات رفتاری موجی-ذراتی از خود نشان می‌دهند.\n\n## برهم‌نهی\n\nیکی از مفاهیم کلیدی، «برهم‌نهی» است: ذره می‌تواند تا پیش از اندازه‌گیری در حالات متعددی به طور هم‌زمان موجود باشد.\n\n## درهم‌تنیدگی\n\nدو ذره می‌توانند به گونه‌ای در هم تنیده شوند که وضعیت یکی فوراً بر دیگری تأثیر بگذارد.\n\n## کاربردها\n\nاز لیزرها و ترانزیستورها گرفته تا رایانش کوانتومی، فناوری‌های مدرن بسیاری به درک ما از مکانیک کوانتومی وابسته‌اند.\n\n> این مقاله صرفاً مقدمه‌ای آموزشی است.', 'published', 1, 3, 5, 5, 'مقدمه‌ای بر مکانیک کوانتومی | AtomicMagazine', 'آشنایی با مفاهیم بنیادی مکانیک کوانتومی', 95, datetime('now'), 'manual', 'طرح مفهومی درباره ذرات و رفتار کوانتومی'),
('ساختار فضا-زمان در کیهان‌شناسی', 'spacetime-cosmology', 'نسبیت عام اینشتین فضا و زمان را به یک شبکه واحد به نام فضا-زمان تبدیل کرد که جرم آن را خم می‌کند.', '# ساختار فضا-زمان در کیهان‌شناسی\n\nدر سال ۱۹۱۵، آلبرت اینشتین با ارائه نسبیت عام، فهم ما از گرانش را دگرگون کرد. او نشان داد که جرم و انرژی، فضا-زمان را خم می‌کنند.\n\n## سیاه‌چاله‌ها\n\nوقتی جرم بسیار زیادی در فضای کوچکی فشرده شود، فضا-زمان تا حدی خم می‌شود که نور نیز نمی‌تواند از آن بگریزد.\n\n## انرژی تاریک\n\nمشاهده انبساط شتاب‌دار کیهان نشان می‌دهد که شاید حدود ۷۰ درصد انرژی جهان به شکل ناشناخته‌ای به نام انرژی تاریک باشد.\n\n> منابع دقیق برای این مقاله وارد نشده‌اند.', 'published', 1, 2, 4, 6, 'ساختار فضا-زمان در کیهان‌شناسی | AtomicMagazine', 'بررسی مفهوم فضا-زمان و نسبیت عام', 88, datetime('now', '-2 days'), 'manual', 'نمایی مفهومی از فضا-زمان و خمیدگی کیهانی'),
('ذرات بنیادی و مدل استاندارد', 'particles-standard-model', 'مدل استاندارد نظریه‌ای است که ذرات بنیادی و نیروهای بنیادی را توصیف می‌کند؛ یکی از دقیق‌ترین نظریه‌های تاریخ فیزیک.', '# ذرات بنیادی و مدل استاندارد\n\nمدل استاندارد نقشه‌ای تقریباً کامل از ذرات بنیادی و نیروهای بنیادی است.\n\n## دسته‌بندی ذرات\n\n- **فرمیون‌ها**: ذرات سازنده ماده مانند کوارک‌ها و لپتون‌ها.\n- **بوزون‌ها**: ذرات حامل نیرو مانند فوتون و گلوئون.\n\n## نیروهای بنیادی\n\nمدل استاندارد، نیروهای الکترومغناطیسی، قوی و ضعیف را در یک چارچوب واحد توصیف می‌کند.\n\n## چالش‌های باقی‌مانده\n\nسیاه‌ماده، انرژی تاریک و ترکیب گرانش با نظریه کوانتومی، هنوز سؤالات باز مدل استاندارد هستند.', 'published', 1, 1, 1, 5, 'ذرات بنیادی و مدل استاندارد | AtomicMagazine', 'مدل استاندارد چیست و چگونه ذرات بنیادی را توصیف می‌کند؟', 82, datetime('now', '-4 days'), 'manual', 'شمای ساده‌ای از ذرات بنیادی و نیروها');
